template <typename UnionPtrType>
ContextCreationAttribsPtr ContextCreationAttribs::Clone() const {
  switch (tag_) {
    case Tag::kGles:
      return NewGles(
          mojo::Clone(data_.gles));
    case Tag::kRaster:
      return NewRaster(
          mojo::Clone(data_.raster));
    case Tag::kWebgpu:
      return NewWebgpu(
          mojo::Clone(data_.webgpu));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, ContextCreationAttribs>::value>::type*>
bool ContextCreationAttribs::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kGles:
      return mojo::Equals(data_.gles, other.data_.gles);
    case Tag::kRaster:
      return mojo::Equals(data_.raster, other.data_.raster);
    case Tag::kWebgpu:
      return mojo::Equals(data_.webgpu, other.data_.webgpu);
  }

  return false;
}
